```yaml
name: Assign milestone to PRs

on:
  pull_request_target:
    types: [opened, reopened]

jobs:
  assign-milestone:
    runs-on: ubuntu-latest
    if: |
      github.event.pull_request.user.login == 'dependabot[bot]' ||
      github.event.pull_request.user.login == 'transifex-integration[bot]' ||
      github.event.pull_request.user.login == 'imgbot[bot]' ||
      github.event.pull_request.user.login == 'BornToBeRoot'
    steps:
      - name: Assign milestone
        uses: actions/github-script@v7
        with:
          github-token: ${{ secrets.GITHUB_TOKEN }}
          script: |
            const milestone = 'next-release';
            const { data: pr } = await github.rest.pulls.get({
              owner: context.repo.owner,
              repo: context.repo.repo,
              pull_number: context.issue.number
            });

            // Check if milestone is already assigned
            if (pr.milestone && pr.milestone.title === milestone) {
              console.log(`Milestone '${milestone}' is already assigned.`);
              return;
            }

            // Find the milestone ID
            const { data: milestones } = await github.rest.issues.listMilestones({
              owner: context.repo.owner,
              repo: context.repo.repo,
              state: 'all',
              title: milestone
            });

            if (milestones.length === 0) {
              console.log(`Milestone '${milestone}' not found.`);
              return;
            }

            const milestoneId = milestones[0].number;

            // Assign the milestone
            await github.rest.issues.update({
              owner: context.repo.owner,
              repo: context.repo.repo,
              issue_number: context.issue.number,
              milestone: milestoneId
            });

            console.log(`Assigned milestone '${milestone}' to PR #${context.issue.number}`);
